package buf

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"go-wind-admin/tools/localdeps/gow/internal/pkg"
)

// preflight verifies every tool, template and input that the locked API chain is about to invoke
// before a single generated byte is written. It exists because api/buf.gen.yaml carries
// clean: true: without this check a missing plugin wipes an output root and then fails, which is
// how a clean checkout lost 347 committed artifacts in measurement.
func preflightGenerate(ctx context.Context, root, apiPath string, templates []*genTemplate) error {
	if err := ensureBufInstalled(ctx); err != nil {
		return err
	}
	cache, err := goModuleCache(ctx)
	if err != nil {
		return err
	}

	var problems []string
	for _, t := range templates {
		for _, dir := range t.InputDirs {
			if !isWithin(apiPath, dir) || !pkg.IsDirExists(filepath.Join(apiPath, dir)) {
				problems = append(problems, fmt.Sprintf("%s: input directory %q does not exist under %s", t.Name, dir, apiPath))
			}
		}
		for _, p := range t.InputPaths {
			if !isWithin(apiPath, p) {
				problems = append(problems, fmt.Sprintf("%s: input path %q escapes the api directory", t.Name, p))
				continue
			}
			if _, err := os.Stat(filepath.Join(apiPath, p)); err != nil {
				problems = append(problems, fmt.Sprintf("%s: input path %q is unreadable: %v", t.Name, p, err))
			}
		}
		for _, ref := range t.Plugins {
			if err := resolvePlugin(ctx, root, apiPath, cache, ref); err != nil {
				problems = append(problems, fmt.Sprintf("%s: %v", t.Name, err))
			}
		}
	}
	if len(problems) > 0 {
		for _, p := range problems {
			_, _ = fmt.Fprintf(os.Stderr, "preflight: %s\n", p)
		}
		return fmt.Errorf("preflight failed with %d problem(s); no generated file was touched", len(problems))
	}
	fmt.Printf("preflight: %d templates, all plugins, inputs and outputs resolved\n", len(templates))
	return nil
}

// resolvePlugin checks one plugin reference. Local build steps are allowed only for the plugin
// this repository owns (protoc-gen-go-redact), through the same script the Makefile uses; nothing
// is ever downloaded or installed by a version the caller did not pin.
func resolvePlugin(ctx context.Context, root, apiPath, cache string, ref pluginRef) error {
	switch ref.Kind {
	case "remote":
		return nil // resolved by buf from the checked-in buf.lock
	case "command":
		if mod, ok := ref.goRunModule(); ok {
			return verifyGoRunModule(cache, mod)
		}
		if _, err := exec.LookPath(ref.Program); err != nil {
			return fmt.Errorf("command %q for %v is not on PATH", ref.Program, ref.Args)
		}
		return nil
	case "path":
		path, err := exec.LookPath(ref.Program)
		if err != nil {
			return fmt.Errorf("plugin %q is not on PATH: %v", ref.Program, err)
		}
		fmt.Printf("preflight: plugin %-22s %s\n", ref.Program, pluginVersion(ctx, path))
		return nil
	case "file":
		target := ref.Program
		if !filepath.IsAbs(target) {
			target = filepath.Join(apiPath, ref.Program)
		}
		if !isWithin(root, target) {
			return fmt.Errorf("plugin path %q escapes the module root", ref.Program)
		}
		if _, err := os.Stat(target); err == nil {
			fmt.Printf("preflight: plugin %-22s present\n", filepath.Base(target))
			return nil
		}
		if filepath.Base(target) != "protoc-gen-go-redact" {
			return fmt.Errorf("plugin %s is missing and this tool does not know how to build it", target)
		}
		fmt.Printf("preflight: %s is missing, building it from pkg/localdeps first\n", filepath.Base(target))
		if err := buildRedactPlugin(ctx, root); err != nil {
			return err
		}
		if _, err := os.Stat(target); err != nil {
			return fmt.Errorf("%s still missing after the build: %v", target, err)
		}
		return nil
	}
	return fmt.Errorf("unhandled plugin reference %q", ref.Raw)
}

// buildRedactPlugin runs the repository's own build script, so the Makefile entry and a direct
// `gow api` share one definition of how that binary is produced.
func buildRedactPlugin(ctx context.Context, root string) error {
	script := filepath.Join(root, "scripts", "build-redact-plugin.sh")
	if _, err := os.Stat(script); err != nil {
		return fmt.Errorf("build script missing: %v", err)
	}
	cmd := exec.CommandContext(ctx, "bash", script)
	cmd.Dir = root
	cmd.Env = os.Environ()
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("building protoc-gen-go-redact failed: %w", err)
	}
	return nil
}

func verifyGoRunModule(cache, mod string) error {
	at := strings.LastIndex(mod, "@")
	if at <= 0 {
		return fmt.Errorf("`go run %s` names no pinned version", mod)
	}
	pkg, version := mod[:at], mod[at+1:]
	if !strings.Contains(pkg, ".") && !strings.Contains(pkg, "/") {
		return fmt.Errorf("%q does not look like a package path", pkg)
	}
	// `go run pkg@version` resolves the module that provides pkg by trying successively
	// shorter path prefixes, so the same search is done here against the local cache.
	// protoc-gen-go lives in module google.golang.org/protobuf while the package is
	// google.golang.org/protobuf/cmd/protoc-gen-go, and protoc-gen-go-grpc is its own module;
	// guessing either way would make the preflight wrong in one direction or the other.
	parts := strings.Split(pkg, "/")
	for i := len(parts); i >= 2; i-- {
		candidate := strings.Join(parts[:i], "/")
		dir := filepath.Join(cache, escapeModulePath(candidate)+"@"+version)
		if _, err := os.Stat(dir); err == nil {
			fmt.Printf("preflight: pinned plugin %s provided by module %s@%s\n", mod, candidate, version)
			return nil
		}
	}
	return fmt.Errorf("pinned plugin %s is not in the module cache under any module prefix of that path (%s); install it explicitly, this tool never fetches or upgrades", mod, cache)
}

// escapeModulePath applies the module cache encoding: every capital letter becomes !lowercase.
func escapeModulePath(path string) string {
	var b strings.Builder
	for _, r := range path {
		if r >= 'A' && r <= 'Z' {
			b.WriteByte('!')
			b.WriteRune(r + ('a' - 'A'))
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}

func goModuleCache(ctx context.Context) (string, error) {
	cctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	out, err := exec.CommandContext(cctx, "go", "env", "GOMODCACHE").Output()
	if err != nil {
		return "", fmt.Errorf("go env GOMODCACHE failed: %w", err)
	}
	cache := strings.TrimSpace(string(out))
	if cache == "" {
		return "", fmt.Errorf("go env GOMODCACHE returned nothing")
	}
	return cache, nil
}

// pluginVersion records a plugin's own version banner. It is capped and fed from /dev/null so a
// plugin that only speaks the protoc protocol on stdin cannot stall the preflight.
func pluginVersion(ctx context.Context, program string) string {
	cctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	devNull, err := os.OpenFile(os.DevNull, os.O_RDONLY, 0)
	if err != nil {
		return "version unreadable"
	}
	defer devNull.Close()
	cmd := exec.CommandContext(cctx, program, "--version")
	cmd.Stdin = devNull
	out, err := cmd.CombinedOutput()
	if err != nil {
		return "version flag unsupported"
	}
	return strings.TrimSpace(string(out))
}

// isWithin keeps a template-declared path inside the base directory after cleaning, so a
// `- ../elsewhere` input or output cannot redirect generation outside the repository.
func isWithin(base, rel string) bool {
	abs := rel
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(base, rel)
	}
	cleanBase, cleanAbs := filepath.Clean(base), filepath.Clean(abs)
	return cleanAbs == cleanBase || strings.HasPrefix(cleanAbs, cleanBase+string(os.PathSeparator))
}
